    var import_external = require("external");
    var Foo = class {
      @&#8203;(123())
      @&#8203;((0, import_external.imported)())
      @&#8203;((void 0)())
      foo;
    };
    ```

-   Allow pre-release versions to be passed to `target` ([#&#8203;3388](https://togithub.com/evanw/esbuild/issues/3388))

